@startuml

class ResearchGroup {
  + name : string
}

class Department {
  + name : string
}

class Researcher {
  + name : string
  + researcherID : int
}

class Project {
  + title : string
  + budget : double
}

class WorkPackage {
  + wpName : string
}

Department "1" -- "*" ResearchGroup
ResearchGroup "1" -- "*" Researcher
Project "1" *-- "1..*" WorkPackage
WorkPackage "*" -- "1" ResearchGroup : ledBy
WorkPackage "*" -- "*" Researcher : teamMember

@enduml

